SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season, TRY_CAST(d.is_final_drive_of_season AS INT) as cast_val
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season, d.is_final_drive_of_season IS NOT NULL AND d.is_final_drive_of_season != 0 as is_final
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49 AND d.is_final_drive_of_season = B'\x01';

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season, typeof(d.is_final_drive_of_season)
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49 AND d.is_final_drive_of_season IS TRUE;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season, d.is_final_drive_of_season IS NOT FALSE
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49;

SELECT d.driver_id, d.year, d.constructor_id, d.is_final_drive_of_season
FROM drives d
WHERE d.year = 2002 AND d.driver_id = 49 AND d.is_final_drive_of_season::INTEGER = 1;

